import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"风水涣","description":"周易折中 - 风水涣","frontmatter":{"title":"风水涣","description":"周易折中 - 风水涣"},"headers":[],"relativePath":"zh/classics/zhezhong/065.md","filePath":"zh/classics/zhezhong/065.md"}'),h={name:"zh/classics/zhezhong/065.md"};function n(d,a,p,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="风水涣" tabindex="-1">风水涣 <a class="header-anchor" href="#风水涣" aria-label="Permalink to “风水涣”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈涣序卦〉：“兑者，说也。说而后散之，故受之以《涣》。《说》则舒散也，人之气，忧则结聚，说则舒散，故说有散义。《涣》所以继《兑》也。为卦，巽上坎下，风行于水上，水遇风则涣散，所以为《涣》也。”</p><p>涣：亨，王假有庙，利涉大川，利贞</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>涣散也，为卦下坎上巽，风行水上，离披解散之象，故为涣。其变则本自渐卦，九来居二而得中，六往居三得九之位而上同于四，故其占可亨。又以祖考之精神既散，故王者当至于庙以聚之。又以巽木坎水舟楫之象，故利涉大川。其曰“利贞”，则占者之深戒也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>涣，离散也。人之离散由乎中，人心离则散矣。治乎散亦本于中，能收拾人心则散可聚也。故卦之义皆主于中。利贞，合涣散之道，在乎正固也。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>涣与萃对，假庙者所以聚鬼神之既散也；涉川者所以聚人力之不齐也。盖尽诚以感格，则幽明无有不应；秦越而共舟，则心力无有不同。此二者，涣而求聚之大端也。然不以正行之，则必有黩神犯难之事故，曰“利贞”。</p><p>象曰：风行水上，涣；先王以享于帝，立庙</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>皆所以合其散。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>风行水上有涣散之象，先王观是象，救天下之涣散，至于享帝立庙也。收合人心，无如宗庙祭祀之报出于其心，故享帝立庙，人心之所归也。系人心合离散之道，无大于此。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>程子曰 ：萃、涣皆享于帝立庙，因其精神之聚而形于此，为其涣散，故立此以收之。</p></li><li><p>吕氏大临曰 ：风行水上，波澜必作，振荡离散不宁之时，王者求以合其散，莫若反其本，享帝立庙，所以明天人之本也。</p></li></ul><p>彖曰：涣 亨，刚来而不穷，柔得位乎外而上同</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦变释卦辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>涣之能亨者，以卦才如是也。涣之成涣，由九来居二六上，居四也。刚阳之来，则不穷极于下而处得其中；柔之往，则得正位于外而上同于五之中。巽顺于五，乃上同也。四五君臣之位，当涣而比，其义相通同。五乃从中也。当涣之时，而守其中，则不至于离散，故能亨也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：二以刚来居内，而不穷于险；四以柔得位乎外，而与上同。内刚而无险困之难，外顺而无违逆之乖，是以亨也。</p></li><li><p>孔氏颖逹曰：此就九二刚徳居险，六四得位从上，释所以能释险难而致亨通。</p></li><li><p>冯氏椅曰：以二四往来明卦义，不穷、上同明亨。刚来不穷，即需刚徤不陷义，不困穷之象。</p></li><li><p>林氏希元曰：柔得位乎外而上同，是六四之柔得位乎外卦而上同九五。四五同徳，斯足以济涣矣，故亨。本义已定，语录虽谓未稳而未及更改。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>刚来而不穷者，固其本也；柔得位乎外而上同者，致其用也。固本则保聚有其基，致用则聫属有其具。</p><p>王假有庙，王乃在中也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>中谓庙中。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>王假有庙之义，在萃卦详矣。天下离散之时，王者收合人心，至于有庙，乃是在其中也。在中谓求得其中，摄其心之谓也。中者，心之象。刚来而不穷，柔得位而上同，卦才之义皆主于中也。王者拯涣之道，在得其中而已。孟子曰：“得其民有道，得其心斯得民矣。”亨帝立庙，民心所归从也。归人心之道，无大于此，故云“至于有庙，拯涣之道极于此也”。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰：王乃在中者，非在庙中之谓。王者之心浑然在中，则不荐之孚，直有出于仪文之外者，宜其精神之与祖考相为感格也。</li></ul><p>利涉大川，乘木有功也</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>治涣之道，当济于险难，而卦有乘木济川之象。上巽木也，下坎水大川也。利涉险以济涣也。木在水上，乘木之象。乘木所以涉川也，涉则有济涣之功。卦有是义，有是象也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：易以巽言利涉大川者三，皆以木言。益曰“木道乃行”，中孚曰“乘木舟虚”，涣曰“乘木有功也”。十三卦舟楫之利，独取诸涣，亦以此也。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>王乃在中，谓九五居中，便含至诚感格之意；乘木有功，谓木在水上，便含济险有具之意。</p><p>初六：用拯马壮，吉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>居卦之初，涣之始也。始涣而拯之，为力既易，又有壮马，其吉可知。初六非有济涣之才，但能顺乎九二，故其象占如此。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>六居卦之初，涣之始也。始涣而拯之，又得马壮，所以吉也。六爻独初不云涣者，离散之势辨之宜早，方始而拯之，则不至于涣也，为教深矣。马人之所托也，托于壮马，故能拯涣。马谓二也，二有刚中之才，初阴柔顺，两皆无应，无应则亲比相求。初之柔顺而托于刚中之才以拯其涣，如得壮马以致远，必有济矣，故吉也。涣拯于始为力则易，时之顺也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰 ：居涣散之初，则时未至于涣也。当此之时，顺此之势而亟救之，则用拯之道得矣，故必马壮而后吉。</p></li><li><p>胡氏炳文曰 ：五爻皆言涣，初独不言者，救之尚早，可不至于涣也。</p></li></ul><p>象曰：初六之吉，顺也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>初之所以吉者，以其能顺从刚中之才也。始涣而用拯，能顺乎时也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：初六难之始也，方难之始而拯之，无不济矣。天下之事，办之于早，则顺而易举。故传曰：“初六之吉，顺也。”</li></ul><p>九二：涣奔其机，悔亡</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>九而居二，宜有悔也。然当涣之时，来而不穷，能亡其悔者也。故其象占如此。盖九奔而二机也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>诸爻皆云涣，谓涣之时也。在涣离之时而处险中，其有悔可知。若能奔就所安，则得悔亡也。机者，俯凭以为安者也，俯就下也，奔急往也。二与初虽非正应，而当涣离之时，两皆无与，以阴阳亲比相求，则相赖者也。故二目初为机，初谓二为马。二急就于初以为安，则能亡其悔矣。初虽坎体而不在险中也。或疑初之柔㣲何足赖，盖涣之时合力为胜。先儒皆以五为机，非也，方涣离之时，二阳岂能同也。若能同，则成济涣之功当大，岂止悔亡而已。机谓俯就也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：大二之刚自外来而得中，得去危就安之义，故有奔其机之象。惟得中就安，故彖传所以言不穷也。</p></li><li><p>朱子语类云 ：九二“涣奔其机”，以人事言之，是来就安处。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>聚涣者先固其本，以刚中居内，固本之象也。机者，所以凭而坐也，有所凭依而安居，然后可以动而不穷矣。</p><p>象曰：涣奔其机，得愿也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>涣散之时，以合为安。二居险中，急就于初，求安也。赖之如机，而亡其悔，乃得所愿也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰 ：当涣之时，以阳刚来居二，二安静之位也，故有“奔其机”之象。夫惟安静，然后能一天下之动。五奠王居于上，而二奔其机于下，各得所安，此所以能合天下之涣也。</li></ul><p>六三：涣其躬，无悔</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>阴柔而不中正，有私于己之象也。然居得阳位，志在济时，能散其私以得无悔，故其占如此。大率此上四爻皆因涣以济涣者也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>三在涣时，独有应与，无涣散之悔也。然以阴柔之质，不中正之才，上居无位之地，岂能拯时之涣而及人也？止于其身，可以无悔而已。上加“涣”字，在涣之时，躬无涣之悔也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰 ：自此以上四爻，皆因涣以拯涣者。谓涣其所当涣，则不当涣者聚矣。案易中六三应上九，少有吉义，惟当涣时，则有应于上者，忘身徇上之象也。蹇之二曰“王臣蹇蹇，匪躬之故”，亦以当蹇难之时，而与五相应，此爻之义同之。</li></ul><p>象曰：涣其躬，志在外也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>志应于上，在外也。与上相应，故其身得免于涣而无悔。悔亡者，本有而得亡；无悔者，本无也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>黄氏淳耀曰 ：外指天下言，惟躬之涣，所以能济天下之涣；惟志在天下之涣，所以有躬之涣也。</li></ul><p>六四：涣其群，元吉；涣有丘，匪夷所思</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>居阴得正，上承九五，当济涣之任者也。下无应与，为能散其朋党之象。占者如是，则大善而吉。又言能散其小群以成大群，使所散者聚而若丘，则非常人思虑之所及也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>涣四五二爻义相须，故通言之。彖故曰“上同也”。四巽顺而正，居大臣之位；五刚中而正，居君位。君臣合力，刚柔相济，以拯天下之涣者也。方涣散之时，用刚则不能使之怀附，用柔则不足为之依归。四以巽顺之正道，辅刚中正之君，君臣同功，所以能济涣也。天下涣散而能使之群聚，可谓大善之吉也。“涣有丘，匪夷所思”，赞美之辞也。丘，聚之大也。方涣散而能致其大聚，其功甚大，其事甚难，其用至妙，夷常也。非平常之见所能思及也，非贤智孰能如是？</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰 ：天下之涣，起于众心乖离，人自为群。六四上承九五，当济涣之任，而居阴得正，下无私应，是大臣秉大公之道，使天下之党尽散，则天下之心不至于乖散，而兼得以萃聚，故得尽善元大之吉也。</p></li><li><p>朱子语类云 ：老苏云：“涣之六四曰‘涣其群，元吉’。夫群者，圣人之所欲涣以混一天下者也。”此说虽程传有所不及。如程传之说，则是群其涣，非涣其群也。盖当人心涣散之时，各相朋党，不能混一。惟六四能涣小人之私群，成天下之公道，此所以元吉也。</p></li><li><p>陈氏琛曰 ：天下之所以涣者，多由人心叛上而各缔其私也。私党既散，则公道大行，而势合于一，如丘陵之高矣。所谓散小群以成大群也。然此必才识之高迈者乃能之，非常人思虑所及也。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>孔安国《书序》云：“丘，聚也。”则“丘”字即训聚。“涣有丘，匪夷所思”，语气盖云常人徒知散之为散，不知散之为聚也。散中有聚，岂常人思虑之所及乎？世有合群党以为自固之术者，然徒以私相结，以势相附耳，非真聚也。及其散也，相背相倾，乃甚于不聚者矣。惟无私者，公道足以服人；惟无邪者，正理可以动众。此所谓散中之聚，人臣体国者之所当知也。</p><p>象曰：涣其群，元吉；光大也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>称元吉者，谓其功德光大也。元吉光大，不在五而在四者，二爻之义通言也。于四言其施用，于五言其成功，君臣之分也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>来氏知德曰 ：凡树私党者，皆心之暗昧狭小者也。惟无一豪之私，则光明正大，自能涣其群矣。故曰光大也。</li></ul><p>九五：涣汗其大号，涣王居，无咎</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>阳刚中正以居尊位，当涣之时，能散其号令与其居积，则可以济涣而无咎矣。故其象占如此。九五巽体有号令之象，汗谓如汗之出而不反也。涣王居，如陆贽所谓散小储而成大储之意。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>五与四君臣合德，以刚中正巽顺之道治涣，得其道矣。惟在浃洽于人心，则顺从也。当使号令洽于民心，如人身之汗浃于四体，则信服而从矣。如是，则可以济天下之涣，居王位为称而无咎。大号，大政令也，谓新民之大命，救涣之大政。再云“涣”，上谓涣之时，下谓处涣，如是则无咎也。在四已言元吉，五惟言称其位也。涣之四五通言者，涣以离散为害，拯之使合也，非君臣同功合力，其能济乎？爻义相须，时之宜也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰 ：汗者，肤腠之所出，出则宣人之壅滞，愈人之疾。犹上有教令，释天下之难，使天下各得其所者。九五居至尊之位，为涣散之主，居得其正，履得其中，能出其号令，布其德泽，宣天下壅滞，发天下堙郁，使天下之人皆信于上，咸有所归，所以居位而无悔咎。</p></li><li><p>朱子语类云 ：圣人就人身上说一汗字为象，不为无意。盖人君之号令当出乎人君之中心，由中而外，由近而远，虽至幽至远之处，无不被而及之，亦犹人身之汗出乎中而浃于四体也。</p></li><li><p>俞氏琰曰 ：散人之疾而使之愈者，汗也；散天下之难而使之愈者，号令也。王居，谓王者所居之位。</p></li><li><p>何氏楷曰 ：王者以天下为一身，欲涣周身之汗，其必有大号以与天下更始，而后可凡大命令之下，大政事之布，大财用之施，以散则为和风，以润则为甘雨。如人之汗从心而液，无不霑透，则群邪之郁积尽涣，而天下之险难亦庶乎可解矣。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>几易中“号”字皆当作平声，为呼号之号。在常人则是哀痛迫切写情输心也，在王者则是至诚恳恻发号施令也。“涣王居”，“涣”字当一读，言其大号也，如涣汗然，足以通上下之壅塞，回周身之元气，则虽当涣之时，而以王者居之，必得无咎矣。</p><p>象曰：王居无咎，正位也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>王居谓正位，人君之尊位也。能如五之为，则居尊位为称而无咎也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>熊氏良辅曰 ：天下涣散之时，须人君𤼵号施令，正位乎上，使人心知所归向，而天下一矣。故曰“王居无咎”，而象曰“正位也”。此与萃“有位”之义同。本义以“涣王居”为“涣其居”，积然当涣散之时，必有为涣之主者，所当从“小象正位”之说。</li></ul><p>上九：涣其血，去逖出，无咎</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>上九以阳居涣极，能出乎涣，故其象占如此。血谓伤害，逖当作惕，与小畜六四同。言涣其血则去，涣其惕则出也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>涣之诸爻皆无系应，亦涣离之象。惟上应于三，三居险陷之极，上若下从于彼，则不能出于涣也。险有伤害畏惧之象，故云血惕。然九以阳刚处涣之外，有出涣之象，又居巽之极为能巽顺于事理，故云若能使其血去其惕出，则无咎也。其者，所有也。涣之时，以能合为功，独九居涣之极，有系而临险，故以能出涣、逺害为善也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：逖，逺也，最逺于害，不近侵克，散其忧伤，逺出者也。散患于逺害之地，谁将咎之哉？</p></li><li><p>朱氏震曰 ：逖，逺也。去逖出，一本作“去惕出”，然象曰“逺害”，当从逖矣。</p></li><li><p>王氏申子曰 ：以诸爻文法律之，“涣其血”句也，涣其所伤而免于难。</p></li><li><p>俞氏琰曰 ：当依爻传作“涣其血”。上居涣终，去坎甚逺而无伤害，故其象为“涣其血”，其占曰“无咎”。</p></li><li><p>钱氏一夲曰 ：去不复来，逖不复近，出不复入。其于坎血，逺而又逺，何咎之有？</p></li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>萃以聚为义，故至卦终而犹赍咨涕洟以求萃者，天命之正，人心之安也。涣以离为义，故至卦终而遂逺害离去以避咎者，亦乐天之智，安土之仁也。古之君子不㓗身以乱伦，亦不濡首以蹈祸，各惟其时而已矣。</p><p>象曰：涣其血，远害也</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>若如象文为“涣其血”，乃与“屯其膏”同也，义则不然。盖“血”字下脱去字，“血去惕出”，谓能远害，则无咎也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰 ：上九爻辞“血”与“出”韵叶，皆三字成句，不以“血”连“去”字也。小畜之“血去惕出”与此不同。此“血已散”，不假更去；又“惕”与“逖”文义自殊。据小象言“远害”也，则“逖”义甚明，不容作“惕”矣。卦中惟上九一爻去险最远，故其辞如此。 又曰：散其汗以去滞郁，散其血以远伤害。</li></ul><p>项氏安世曰 ：上九爻辞“血”与“出”韵叶，皆三字成句，不以“血”连“去”字也。小畜之“血去惕出”与此不同。此“血已散”，不假更去；又“惕”与“逖”文义自殊。据小象言“远害”也，则“逖”义甚明，不容作“惕”矣。卦中惟上九一爻去险最远，故其辞如此。</p><ul><li><p>又曰：散其汗以去滞郁，散其血以远伤害。</p></li><li><p>陈氏友文曰 ：坎为血，卦逖远也。小象“远害”正是以“远”释“逖”字。上虽与三应，然超处涣上，故涣散其血，舍之远去，去坎险之害而得无咎也。</p></li></ul><p>陈氏友文曰 ：坎为血，卦逖远也。小象“远害”正是以“远”释“逖”字。上虽与三应，然超处涣上，故涣散其血，舍之远去，去坎险之害而得无咎也。</p>',123)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
